<?php header('Content-Type: application/json');try{$c=require __DIR__.'/config.php';$p=new PDO("mysql:host={$c['db_host']};dbname={$c['db_name']};charset=utf8mb4",$c['db_user'],$c['db_pass'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);$a=$_GET['action']??'stats';$d=json_decode(file_get_contents('php://input'),true)??[];
