if($a==='product'){$id=(int)($d['id']??0);if($id){$s=$p->prepare("UPDATE products SET name=?,category=?,price=?,image_url=?,icon=?,details=?,featured=?,active=? WHERE id=?");$s->execute([$d['name'],$d['category'],$d['price'],$d['image_url']??'',$d['icon']??'▣',$d['details']??'',$d['featured']??0,$d['active']??1,$id]);}else{$s=$p->prepare("INSERT INTO products(name,category,price,image_url,icon,details,featured,active) VALUES(?,?,?,?,?,?,?,?)");$s->execute([$d['name'],$d['category'],$d['price'],$d['image_url']??'',$d['icon']??'▣',$d['details']??'',$d['featured']??0,$d['active']??1]);}echo json_encode(['success'=>true]);exit;}
